import { readFileSync } from 'node:fs'

/**
 * Service dependencies between plugins, generated by scripts/gen-deps.mjs.
 *
 * Only services that a preset has to load a provider for are kept. Services the host or the
 * base bundles already supply (fs, llm, agents, ...) are left out, so they never produce a warning.
 *
 * @returns {{ requires: Record<string, string[]>, providers: Record<string, string[]>, conflicts: Record<string, string[]> }}
 *   `requires[module]` lists the checked services that module injects;
 *   `providers[service]` lists the modules that provide the service;
 *   `conflicts[toolName]` lists the modules that register the same model-visible tool name.
 */
export function loadDeps(file = new URL('./deps.json', import.meta.url)) {
  let raw
  try { raw = JSON.parse(readFileSync(file, 'utf8')) } catch { return { requires: {}, providers: {}, conflicts: {} } }
  const providers = raw.providers ?? {}
  const requires = {}
  for (const [module, services] of Object.entries(raw.injects ?? {})) {
    const checked = services.filter(service => Array.isArray(providers[service]) && providers[service].length > 0)
    if (checked.length > 0) requires[module] = checked
  }
  const used = new Set(Object.values(requires).flat())
  return {
    requires,
    providers: Object.fromEntries(Object.entries(providers).filter(([service]) => used.has(service))),
    conflicts: raw.conflicts ?? {},
  }
}
